using System.Net;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
namespace Orbit.Core;
public sealed record ModCategory(string Id,string Title);
public sealed record ModProject(string Id,string Slug,string Title,string Description,string Author,long Downloads,string[] Categories,string IconUrl="");
public sealed record ModSearch(IReadOnlyList<ModProject> Projects,int Total);
public sealed record ModArtifact(string Project,string Version,string Name,string Filename,string Url,string Sha512,long Size);
public sealed record ModPlan(string GameVersion,string Loader,IReadOnlyList<ModArtifact> Files){public string ProjectType{get;init;}="mod";public string ContentFolder=>ProjectType switch{"mod"=>"mods","resourcepack"=>"resourcepacks","shader"=>"shaderpacks",_=>throw new InvalidDataException(Localization.T("Неподдерживаемый тип дополнения."))};}
public sealed record ModProgress(string Stage,long Done,long Total);
public sealed class ModrinthClient:IDisposable {
 readonly HttpClient http;
 public ModrinthClient(HttpMessageHandler? handler=null){http=new HttpClient(handler??new HttpClientHandler{AllowAutoRedirect=false,AutomaticDecompression=DecompressionMethods.All}){Timeout=TimeSpan.FromSeconds(90)};http.DefaultRequestHeaders.UserAgent.ParseAdd("ORBIT/0.4 (local Minecraft launcher)");}
 public void Dispose()=>http.Dispose();
 static string Q(string value)=>Uri.EscapeDataString(value);
 static string Id(string id)=>Regex.IsMatch(id,"^[a-zA-Z0-9_-]{1,160}$")?id:throw new InvalidDataException(Localization.T("Некорректный ID Modrinth."));
 public static string Loader(string loader)=>loader.ToLowerInvariant() is "fabric" or "forge" or "neoforge" or "quilt"?loader.ToLowerInvariant():throw new InvalidDataException(Localization.T("Для модов выбери установленную сборку Fabric, Forge, NeoForge или Quilt в нижней панели."));
 public static Uri DownloadUri(string url){if(!Uri.TryCreate(url,UriKind.Absolute,out var uri)||uri.Scheme!="https"||uri.Host!="cdn.modrinth.com"||!uri.IsDefaultPort||uri.UserInfo!="")throw new InvalidDataException(Localization.T("Файл должен находиться на HTTPS CDN Modrinth."));return uri;}
 async Task<JsonNode> Api(string path,CancellationToken ct){using var response=await http.GetAsync("https://api.modrinth.com/v2/"+path,HttpCompletionOption.ResponseHeadersRead,ct).ConfigureAwait(false);if(response.StatusCode==(HttpStatusCode)429)throw new IOException(Localization.T("Modrinth просит подождать. Повтори запрос чуть позже."));response.EnsureSuccessStatusCode();using var stream=await response.Content.ReadAsStreamAsync(ct).ConfigureAwait(false);using var buffer=new MemoryStream();byte[] chunk=new byte[65536];int n;while((n=await stream.ReadAsync(chunk,ct).ConfigureAwait(false))>0){if(buffer.Length+n>24*1024*1024)throw new InvalidDataException(Localization.T("Слишком большой ответ Modrinth."));buffer.Write(chunk,0,n);}return JsonNode.Parse(buffer.ToArray())??throw new InvalidDataException(Localization.T("Пустой ответ Modrinth."));}
 static string S(JsonNode? node,string key)=>node?[key]?.ToString()??"";
 static string[] A(JsonNode? node,string key)=>node?[key]?.AsArray().Select(x=>x!.ToString()).ToArray()??Array.Empty<string>();
 public async Task<IReadOnlyList<ModCategory>> CategoriesAsync(CancellationToken ct=default,string projectType="mod"){var data=await Api("tag/category",ct);return data.AsArray().Where(n=>S(n,"project_type")==projectType).Select(n=>new ModCategory(S(n,"name"),CategoryTitle(S(n,"name")))).OrderBy(n=>n.Title).ToList();}
 public static string CategoryTitle(string id)=>id switch{"adventure"=>Localization.T("Приключения"),"decoration"=>Localization.T("Декор"),"equipment"=>Localization.T("Снаряжение"),"food"=>Localization.T("Еда"),"game-mechanics"=>Localization.T("Механики"),"library"=>Localization.T("Библиотеки"),"magic"=>Localization.T("Магия"),"management"=>Localization.T("Управление"),"mobs"=>Localization.T("Мобы"),"optimization"=>Localization.T("Оптимизация"),"social"=>Localization.T("Социальное"),"storage"=>Localization.T("Хранение"),"technology"=>Localization.T("Технологии"),"transportation"=>Localization.T("Транспорт"),"utility"=>Localization.T("Утилиты"),"worldgen"=>Localization.T("Генерация мира"),"combat"=>Localization.T("Бой"),"realistic"=>Localization.T("Реалистичные"),"simplistic"=>Localization.T("Минимализм"),"themed"=>Localization.T("Тематические"),"vanilla-like"=>Localization.T("В стиле Vanilla"),"audio"=>Localization.T("Звуки"),"blocks"=>Localization.T("Блоки"),"entities"=>Localization.T("Существа"),"environment"=>Localization.T("Окружение"),"fonts"=>Localization.T("Шрифты"),"gui"=>Localization.T("Интерфейс"),"items"=>Localization.T("Предметы"),"models"=>Localization.T("Модели"),"locale"=>Localization.T("Переводы"),"tweaks"=>Localization.T("Улучшения"),_=>id};
 public async Task<ModSearch> SearchAsync(string query,string gameVersion,string? loader,string category,int offset,string sort,CancellationToken ct=default,string projectType="mod"){if(projectType is not("mod" or "resourcepack" or "shader" or "modpack"))throw new InvalidDataException(Localization.T("Тип каталога не поддерживается."));var facets=new List<string[]>{new[]{"project_type:"+projectType},new[]{"client_side!=unsupported"}};if(gameVersion.Length>0)facets.Add(new[]{"versions:"+gameVersion});if(loader!=null&&projectType=="mod")facets.Add(new[]{"categories:"+Loader(loader)});if(category!="")facets.Add(new[]{"categories:"+Id(category)});if(sort is not("downloads" or "relevance" or "newest" or "updated"))sort="relevance";var data=await Api("search?limit=20&offset="+Math.Max(0,offset)+"&query="+Q(query)+"&index="+sort+"&facets="+Q(JsonSerializer.Serialize(facets)),ct);return new(data["hits"]!.AsArray().Select(n=>new ModProject(S(n,"project_id"),S(n,"slug"),S(n,"title"),S(n,"description"),S(n,"author"),n!["downloads"]!.GetValue<long>(),A(n,"categories"),S(n,"icon_url"))).ToList(),data["total_hits"]!.GetValue<int>());}
 public async Task<ModPlan> ResolveAsync(string project,string gameVersion,string loader,CancellationToken ct=default,string projectType="mod"){if(projectType is not("mod" or "resourcepack" or "shader"))throw new InvalidDataException(Localization.T("Тип каталога не поддерживается."));bool pack=projectType=="resourcepack",zipContent=projectType!="mod";string[] compatibleLoaders=projectType switch{"resourcepack"=>new[]{"minecraft"},"shader"=>new[]{"iris","optifine"},_=>new[]{Loader(loader)}};loader=string.Join("/",compatibleLoaders);var resolved=new Dictionary<string,ModArtifact>();var visiting=new HashSet<string>();var incompatible=new List<(string? Project,string? Version)>();
  async Task<JsonNode> Latest(string id){var list=(await Api("project/"+Id(id)+"/version?include_changelog=false&game_versions="+Q(JsonSerializer.Serialize(new[]{gameVersion}))+"&loaders="+Q(JsonSerializer.Serialize(compatibleLoaders)),ct)).AsArray();return list.Where(n=>S(n,"status") is not("draft" or "scheduled")&&S(n,"environment") is not("server_only" or "dedicated_server_only")).OrderBy(n=>S(n,"version_type")=="release"?0:1).ThenByDescending(n=>S(n,"date_published")).FirstOrDefault()??throw new IOException(Localization.T("Нет совместимой версии мода ")+id+Localization.T(" для ")+gameVersion+" / "+loader+".");}
  async Task Visit(JsonNode version){ct.ThrowIfCancellationRequested();string pid=Id(S(version,"project_id")),vid=Id(S(version,"id"));if(resolved.TryGetValue(pid,out var old)){if(old.Version!=vid)throw new IOException(Localization.T("Зависимости требуют разные версии одного мода: ")+pid);return;}if(resolved.Count+visiting.Count>=100)throw new IOException(Localization.T("Слишком много зависимостей."));if(!visiting.Add(pid))throw new IOException(Localization.T("Циклическая зависимость модов."));if(!A(version,"game_versions").Contains(gameVersion)||!A(version,"loaders").Intersect(compatibleLoaders).Any())throw new IOException(Localization.T("Зависимость несовместима с выбранной сборкой: ")+pid);
   foreach(var dep in version["dependencies"]?.AsArray()??new JsonArray()){string kind=S(dep,"dependency_type");if(kind=="incompatible"){incompatible.Add((dep?["project_id"]?.ToString(),dep?["version_id"]?.ToString()));continue;}if(kind!="required")continue;JsonNode next;if(S(dep,"version_id") is {Length:>0} exact)next=await Api("version/"+Id(exact),ct);else if(S(dep,"project_id") is {Length:>0} dependency)next=await Latest(dependency);else throw new IOException(Localization.T("Мод требует внешнюю зависимость, которую нельзя установить автоматически."));await Visit(next);}
   var candidates=version["files"]!.AsArray().Where(n=>S(n,"filename").EndsWith(zipContent?".zip":".jar",StringComparison.OrdinalIgnoreCase)).ToList();var file=candidates.FirstOrDefault(n=>n?["primary"]?.GetValue<bool>()==true)??(candidates.Count==1?candidates[0]:null)??throw new IOException(Localization.T("У версии нет однозначного основного файла нужного типа."));string filename=S(file,"filename");MojangInstaller.ValidateId(filename);string hash=S(file?["hashes"],"sha512");if(!Regex.IsMatch(hash,"^[a-fA-F0-9]{128}$"))throw new InvalidDataException(Localization.T("Modrinth не предоставил SHA-512 файла."));long size=file!["size"]!.GetValue<long>();if(size<=0||size>512L*1024*1024)throw new InvalidDataException(Localization.T("Неподдерживаемый размер мода."));DownloadUri(S(file,"url"));resolved.Add(pid,new(pid,vid,S(version,"name"),filename,S(file,"url"),hash,size));visiting.Remove(pid);
  }
  await Visit(await Latest(project));foreach(var conflict in incompatible)if(resolved.Values.Any(v=>v.Project==conflict.Project||v.Version==conflict.Version))throw new IOException(Localization.T("Между выбранными модами есть несовместимость."));return new(gameVersion,loader,resolved.Values.ToArray()){ProjectType=projectType};
 }
 public async Task InstallAsync(ModPlan plan,string gameDirectory,IProgress<ModProgress>? progress=null,CancellationToken ct=default){if(plan.Files.Count==0)return;string folder=plan.ContentFolder;string orbit=Path.Combine(gameDirectory,".orbit");Directory.CreateDirectory(orbit);using var installLock=new FileStream(Path.Combine(orbit,"modrinth.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);string manifest=Path.Combine(orbit,plan.ProjectType switch{"resourcepack"=>"modrinth-resourcepacks.json","shader"=>"modrinth-shaders.json",_=>"modrinth.json"});var installed=File.Exists(manifest)?JsonSerializer.Deserialize<List<ModArtifact>>(await File.ReadAllTextAsync(manifest,ct))??new():new List<ModArtifact>();foreach(var f in plan.Files)if(installed.Any(x=>x.Project==f.Project&&x.Version!=f.Version&&File.Exists(Versions.Within(Path.Combine(gameDirectory,folder),x.Filename))))throw new IOException(Localization.T("Другая версия мода уже установлена. Удали её файл из папки дополнений перед заменой: ")+f.Project);
  string staging=Path.Combine(orbit,"downloads-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(staging);string mods=Path.Combine(gameDirectory,folder);var added=new List<string>();long done=0,total=plan.Files.Sum(f=>f.Size);if(total>2L*1024*1024*1024)throw new IOException(Localization.T("Суммарный размер модов слишком большой."));
  try{foreach(var f in plan.Files){ct.ThrowIfCancellationRequested();string staged=Versions.Within(staging,f.Filename);if(File.Exists(staged))throw new IOException(Localization.T("Зависимости используют одинаковые имена файлов."));string target=Versions.Within(mods,f.Filename);if(File.Exists(target)){using var existing=File.OpenRead(target);if(!Convert.ToHexString(await SHA512.HashDataAsync(existing,ct)).Equals(f.Sha512,StringComparison.OrdinalIgnoreCase))throw new IOException(Localization.T("Файл с таким именем уже существует и отличается: ")+f.Filename);done+=f.Size;progress?.Report(new(f.Name,done,total));continue;}
    using var response=await http.GetAsync(DownloadUri(f.Url),HttpCompletionOption.ResponseHeadersRead,ct).ConfigureAwait(false);response.EnsureSuccessStatusCode();using var input=await response.Content.ReadAsStreamAsync(ct).ConfigureAwait(false);using(var output=new FileStream(staged,FileMode.CreateNew,FileAccess.Write,FileShare.None,65536,true)){using var hash=IncrementalHash.CreateHash(HashAlgorithmName.SHA512);byte[] buffer=new byte[65536];long count=0;int n;while((n=await input.ReadAsync(buffer,ct).ConfigureAwait(false))>0){count+=n;if(count>f.Size)throw new InvalidDataException(Localization.T("Размер мода не совпал: ")+f.Filename);hash.AppendData(buffer,0,n);await output.WriteAsync(buffer.AsMemory(0,n),ct).ConfigureAwait(false);done+=n;progress?.Report(new(f.Name,done,total));}if(count!=f.Size||!Convert.ToHexString(hash.GetHashAndReset()).Equals(f.Sha512,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException(Localization.T("Проверка SHA-512 не пройдена: ")+f.Filename);}}
   if(plan.ProjectType=="resourcepack")foreach(var f in plan.Files){string staged=Versions.Within(staging,f.Filename);if(!File.Exists(staged))continue;using var archive=ZipFile.OpenRead(staged);if(archive.GetEntry("pack.mcmeta")==null)throw new InvalidDataException(Localization.T("ZIP не содержит pack.mcmeta в корне: ")+f.Filename);}
   if(plan.ProjectType=="shader")foreach(var f in plan.Files){string staged=Versions.Within(staging,f.Filename);if(!File.Exists(staged))continue;using var archive=ZipFile.OpenRead(staged);if(!archive.Entries.Any(e=>e.FullName.StartsWith("shaders/",StringComparison.OrdinalIgnoreCase)&&new[]{".fsh",".vsh",".glsl",".csh"}.Contains(Path.GetExtension(e.FullName).ToLowerInvariant())))throw new InvalidDataException(Localization.T("В ZIP нет файлов шейдера в папке shaders: ")+f.Filename);}
   ct.ThrowIfCancellationRequested();Directory.CreateDirectory(mods);foreach(var f in plan.Files){string staged=Versions.Within(staging,f.Filename);if(!File.Exists(staged))continue;string target=Versions.Within(mods,f.Filename);File.Move(staged,target,false);added.Add(target);}installed.RemoveAll(x=>plan.Files.Any(f=>f.Project==x.Project));installed.AddRange(plan.Files);await File.WriteAllTextAsync(manifest+".new",JsonSerializer.Serialize(installed,new JsonSerializerOptions{WriteIndented=true}),CancellationToken.None);File.Move(manifest+".new",manifest,true);
  }catch{foreach(string path in added)File.Delete(path);throw;}finally{Directory.Delete(staging,true);}
 }
}
